<script setup>
import { reactive } from 'vue';
import { Link,useForm } from '@inertiajs/vue3';
const props=defineProps({branch:Object,suppliers:Array,ingredients:Array,orders:Object});
const form=useForm({supplier_id:'',notes:'',items:[{ingredient_id:'',quantity_ordered:1,unit_cost:0}]});
const receiveForms=reactive({});
for(const order of props.orders.data){receiveForms[order.id]=useForm({idempotency_key:crypto.randomUUID(),notes:'',items:order.items.filter(i=>Number(i.quantity_ordered)>Number(i.quantity_received)).map(i=>({purchase_order_item_id:i.id,received_qty:''}))});}
function addItem(){form.items.push({ingredient_id:'',quantity_ordered:1,unit_cost:0});}
function createOrder(){form.post(`/admin/branches/${props.branch.id}/inventory/purchases`,{preserveScroll:true,onSuccess:()=>form.reset()});}
function receive(orderId){receiveForms[orderId].post(`/admin/branches/${props.branch.id}/inventory/purchases/${orderId}/receive`,{preserveScroll:true,onSuccess:()=>{const updated=props.orders.data.find(o=>o.id===orderId);receiveForms[orderId].idempotency_key=crypto.randomUUID();receiveForms[orderId].items=(updated?.items||[]).filter(i=>Number(i.quantity_ordered)>Number(i.quantity_received)).map(i=>({purchase_order_item_id:i.id,received_qty:''}));receiveForms[orderId].notes='';}});}
const qty=(v)=>Number(v||0).toLocaleString('ar-EG',{maximumFractionDigits:3});
</script>
<template><main dir="rtl" class="mx-auto max-w-7xl space-y-6 p-4 sm:p-6"><header><Link :href="`/admin/branches/${branch.id}/inventory`" class="text-sm font-bold text-amber-700">المخزون</Link><h1 class="mt-1 text-3xl font-black">المشتريات والاستلام</h1><p class="mt-1 text-sm text-slate-500">أوامر شراء بكميات بوحدة الأساس للمكون، مع استلام جزئي آمن.</p></header>
<form @submit.prevent="createOrder" class="space-y-4 rounded-2xl border bg-white p-5"><h2 class="font-black">إنشاء أمر شراء</h2><label class="block text-sm font-semibold">المورد<select v-model="form.supplier_id" required class="mt-1 w-full rounded-lg border-slate-300 sm:max-w-md"><option value="">اختر المورد</option><option v-for="s in suppliers" :key="s.id" :value="s.id">{{s.name}}</option></select></label><div v-for="(item,index) in form.items" :key="index" class="grid gap-2 rounded-xl bg-slate-50 p-3 sm:grid-cols-3"><select v-model="item.ingredient_id" required class="rounded-lg border-slate-300 text-sm"><option value="">المكون</option><option v-for="i in ingredients" :key="i.id" :value="i.id">{{i.name}} ({{i.base_unit_symbol}})</option></select><input v-model.number="item.quantity_ordered" required type="number" min="0.001" step="0.001" placeholder="الكمية" class="rounded-lg border-slate-300 text-sm"/><input v-model.number="item.unit_cost" required type="number" min="0" step="0.0001" placeholder="تكلفة وحدة الأساس" class="rounded-lg border-slate-300 text-sm"/></div><button type="button" @click="addItem" class="text-sm font-bold text-amber-700">+ إضافة مكون</button><textarea v-model="form.notes" rows="2" placeholder="ملاحظات أمر الشراء" class="w-full rounded-lg border-slate-300 text-sm"/><button :disabled="form.processing||!suppliers.length||!ingredients.length" class="rounded-lg bg-slate-900 px-5 py-2.5 font-bold text-white">إنشاء أمر الشراء</button><p v-if="Object.keys(form.errors).length" class="text-sm text-rose-600">{{Object.values(form.errors).join(' · ')}}</p></form>
<section class="space-y-4"><h2 class="text-xl font-black">أوامر الشراء</h2><article v-for="order in orders.data" :key="order.id" class="space-y-4 rounded-2xl border bg-white p-5"><div class="flex flex-wrap items-center justify-between gap-2"><div><p class="font-black">{{order.purchase_number}}</p><p class="mt-1 text-xs text-slate-500">{{order.supplier?.name}} · {{new Date(order.ordered_at).toLocaleString('ar-EG')}}</p></div><span class="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{{({ordered:'مطلوب',partially_received:'استلام جزئي',received:'مكتمل',cancelled:'ملغي',draft:'مسودة'})[order.status]||order.status}}</span></div><div class="overflow-x-auto"><table class="w-full min-w-[500px] text-right text-sm"><thead class="text-xs text-slate-500"><tr><th class="py-2">المكون</th><th>المطلوب</th><th>المستلم</th><th>تكلفة الوحدة</th></tr></thead><tbody><tr v-for="item in order.items" :key="item.id" class="border-t"><td class="py-2 font-semibold">{{item.ingredient?.name}}</td><td>{{qty(item.quantity_ordered)}}</td><td>{{qty(item.quantity_received)}}</td><td>{{Number(item.unit_cost).toFixed(4)}} EGP</td></tr></tbody></table></div><form v-if="!['received','cancelled'].includes(order.status) && receiveForms[order.id]?.items.length" @submit.prevent="receive(order.id)" class="space-y-2 rounded-xl bg-amber-50 p-3"><p class="text-sm font-black">تسجيل استلام جديد</p><div v-for="item in receiveForms[order.id].items" :key="item.purchase_order_item_id" class="flex flex-wrap gap-2"><label class="flex-1 text-xs text-slate-600">كمية الاستلام للصنف #{{item.purchase_order_item_id}}<input v-model="item.received_qty" required type="number" min="0.001" step="0.001" class="mt-1 w-full rounded-lg border-slate-300 text-sm"/></label></div><input v-model="receiveForms[order.id].notes" placeholder="ملاحظات الاستلام" class="w-full rounded-lg border-slate-300 text-sm"/><button class="rounded-lg bg-amber-700 px-4 py-2 text-sm font-bold text-white">تأكيد الاستلام</button><p v-if="Object.keys(receiveForms[order.id].errors).length" class="text-sm text-rose-700">{{Object.values(receiveForms[order.id].errors).join(' · ')}}</p></form></article><p v-if="!orders.data.length" class="rounded-xl border border-dashed p-8 text-center text-sm text-slate-500">لا توجد أوامر شراء.</p></section></main></template>
